import{_ as s,a as l,b as e,c,d as g,e as i,f as h,g as d,h as p,i as m,j as u,k as y,l as w,m as f,n as _,o as b,p as x,q as k,r as v,s as z,t as q,u as I,v as P,w as S,x as A,y as C,z as j,A as D,B as T,C as O,D as R,E,F as L,G as F,H as W,I as B,J as N,K as V,L as G,M,N as J,O as K,P as H,Q as U,R as Q,S as $,T as Z,U as X,V as Y,W as tt,X as et,Y as it,Z as ot,$ as at}from"./chunks/image5.BiYg8OGh.js";import{_ as nt,a as n}from"./chunks/100.C758gORP.js";import{_ as rt,a as st,b as o,c as lt,d as ct,e as gt,f as t,g as ht,h as dt,i as pt,j as mt,k as ut,l as r,m as yt}from"./chunks/image8.tTV-mUTh.js";import{_ as wt,o as ft,c as _t,ak as bt}from"./chunks/framework.DyMoXumJ.js";const xt="/projects/AIVisionKit/en/latest/assets/3.Cl3r7F88.webp",kt="/projects/AIVisionKit/en/latest/assets/2.Xm1ewtlL.webp",vt="/projects/AIVisionKit/en/latest/assets/1.cpEc7kIx.webp",zt="/projects/AIVisionKit/en/latest/assets/2.bAIId2_h.webp",qt="/projects/AIVisionKit/en/latest/assets/3.ojat9ZDD.webp",It="/projects/AIVisionKit/en/latest/assets/4.D4wg-yvh.webp",Pt="/projects/AIVisionKit/en/latest/assets/14.CZPuH50r.webp",St="/projects/AIVisionKit/en/latest/assets/5.DnCbzHiS.webp",At="/projects/AIVisionKit/en/latest/assets/12.DPquGiMk.webp",Ct="/projects/AIVisionKit/en/latest/assets/15.D-RJiU61.webp",jt="/projects/AIVisionKit/en/latest/assets/image3.BFgbNyds.webp",Dt="/projects/AIVisionKit/en/latest/assets/image6.JIZr26Zo.webp",Tt="/projects/AIVisionKit/en/latest/assets/13.Cj7uwKf3.webp",Jt=JSON.parse('{"title":"2. Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2. Quick Start.md","filePath":"docs/2. Quick Start.md"}'),Ot={name:"docs/2. Quick Start.md"};function Rt(Et,a,Lt,Ft,Wt,Bt){return ft(),_t("div",null,[...a[0]||(a[0]=[bt('<h1 id="_2-quick-start" tabindex="-1">2. Quick Start <a class="header-anchor" href="#_2-quick-start" aria-label="Permalink to &quot;2. Quick Start&quot;">​</a></h1><h2 id="_2-1-wonderlens-ai-vision-module-basic-experience" tabindex="-1">2.1 WonderLens AI Vision Module Basic Experience <a class="header-anchor" href="#_2-1-wonderlens-ai-vision-module-basic-experience" aria-label="Permalink to &quot;2.1 WonderLens AI Vision Module Basic Experience&quot;">​</a></h2><h3 id="_2-1-1-powering-on-the-device" tabindex="-1">2.1.1 Powering On the Device <a class="header-anchor" href="#_2-1-1-powering-on-the-device" aria-label="Permalink to &quot;2.1.1 Powering On the Device&quot;">​</a></h3><img loading="lazy" height="825" width="2000" src="'+s+'" class="common_img" style="width:500px;aspect-ratio:2000 / 825;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>The supply voltage for the WonderLens AI vision module must not exceed 5 V. Always select a charging adapter or lithium battery that outputs 5 V or less.</strong></p></li><li><p><strong>Ensure sufficient supply voltage and power capacity. Otherwise, the WonderLens AI vision module may experience screen flickering, incorrect detection results, or other abnormal behaviors.</strong></p></li></ul></div><p><a id="section-2-1-2"></a></p><h3 id="_2-1-2-operating-instructions" tabindex="-1">2.1.2 Operating Instructions <a class="header-anchor" href="#_2-1-2-operating-instructions" aria-label="Permalink to &quot;2.1.2 Operating Instructions&quot;">​</a></h3><h4 id="_1-basic-operations" tabindex="-1">(1) Basic Operations <a class="header-anchor" href="#_1-basic-operations" aria-label="Permalink to &quot;(1) Basic Operations&quot;">​</a></h4><p>The WonderLens AI vision module features two joysticks located on the left and right sides. Each joystick can be toggled left, toggled right, or pressed downward. Functionally, these controls serve as the <strong>Navigation Joystick</strong> and the <strong>Function Joystick</strong>. The joystick in the upper-left corner of the screen functions as the navigation joystick, while the one in the upper-right corner serves as the function joystick, as shown in the following figure:</p><img loading="lazy" height="1926" width="4721" src="'+l+'" class="common_img" style="width:700px;aspect-ratio:4721 / 1926;"><table tabindex="0"><thead><tr><th style="text-align:center;">Operation</th><th style="text-align:center;">Navigation Joystick</th><th style="text-align:center;">Function Joystick</th></tr></thead><tbody><tr><td style="text-align:center;">Toggle left</td><td style="text-align:center;">Switch menu items left</td><td style="text-align:center;">Enter learning mode</td></tr><tr><td style="text-align:center;">Press</td><td style="text-align:center;">Collapse taskbar or exit</td><td style="text-align:center;">Confirm or setting</td></tr><tr><td style="text-align:center;">Toggle right</td><td style="text-align:center;">Switch menu items right</td><td style="text-align:center;">Fill light toggle or delete</td></tr></tbody></table><h4 id="_2-color-recognition" tabindex="-1">(2) Color Recognition <a class="header-anchor" href="#_2-color-recognition" aria-label="Permalink to &quot;(2) Color Recognition&quot;">​</a></h4><ol><li><p><strong>Entering the Mode</strong></p><ul><li><p>Upon initial startup, the screen stays on the &quot;Color Recognition&quot; function bar.</p></li><li><p>Return to the main interface and toggle the <strong>Navigation Joystick</strong> until the &quot;Color Recognition&quot; menu bar appears at the top of the screen.</p></li></ul></li><li><p><strong>Learning and Recognizing New Colors</strong></p><p>Before using the color recognition function, the target color must be learned. The learning steps are as follows:</p><p>(1) On the main Color Recognition screen, toggle the <strong>Function Joystick</strong> to the pen icon <img loading="lazy" height="47" width="50" src="'+e+'" class="inline-icon" style="width:35px;aspect-ratio:50 / 47;"> to enter the learning interface.</p><img loading="lazy" height="904" width="1200" src="'+c+'" class="common_img" style="width:500px;aspect-ratio:1200 / 904;"><p>(2) Align the crosshairs in the center of the screen with the color patch to be learned. The selected color patch will be highlighted by a white bounding box.</p><img loading="lazy" height="905" width="1200" src="'+g+'" class="common_img" style="width:500px;aspect-ratio:1200 / 905;"><p>(3) Toggle the joystick left, then press the <strong>Function Joystick</strong> at the camera icon <img loading="lazy" height="38" width="46" src="'+i+'" class="inline-icon" style="width:40px;aspect-ratio:46 / 38;"> to begin learning. Once learning succeeds, a confirmation prompt appears on the screen.</p><img loading="lazy" height="904" width="1200" src="'+h+'" class="common_img" style="width:500px;aspect-ratio:1200 / 904;"><p>(4) After successful learning, whenever the vision module detects the recognized color in the frame, it immediately highlights the largest matching object and displays the corresponding color ID.</p><img loading="lazy" height="904" width="1200" src="'+d+'" class="common_img" style="width:500px;aspect-ratio:1200 / 904;"><img loading="lazy" height="904" width="1200" src="'+p+'" class="common_img" style="width:500px;aspect-ratio:1200 / 904;"></li></ol><ul><li><strong>For instructions on deleting color recognition IDs and configuring related parameters, refer to <a href="https://wiki.hiwonder.com/projects/AIVisionKit/en/latest/docs/4.%20Software%20and%20Hardware%20Guide.html#_4-4-4-function-introduction" target="_blank" rel="noreferrer">4. Software and Hardware Guide / 4.4 WonderLens AI vision module / 4.4.4 Function Introduction</a></strong>.</li></ul><h4 id="_3-facial-recognition" tabindex="-1">(3) Facial Recognition <a class="header-anchor" href="#_3-facial-recognition" aria-label="Permalink to &quot;(3) Facial Recognition&quot;">​</a></h4><ol><li><p><strong>Entering the Mode</strong></p><p>Return to the main interface and toggle the <strong>Navigation Joystick</strong> until the &quot;Facial Recognition&quot; menu bar appears at the top of the screen.</p></li><li><p><strong>Detecting Faces</strong></p><p>Once this mode is entered, face detection starts running automatically. When a face is successfully detected, it is highlighted with a white bounding box.</p><img loading="lazy" height="905" width="1200" src="'+m+'" class="common_img" style="width:500px;aspect-ratio:1200 / 905;"><img loading="lazy" height="905" width="1200" src="'+u+'" class="common_img" style="width:500px;aspect-ratio:1200 / 905;"></li></ol><ul><li><strong>For face recognition learning steps and parameter configuration details, refer to <a href="https://wiki.hiwonder.com/projects/AIVisionKit/en/latest/docs/4.%20Software%20and%20Hardware%20Guide.html#_4-4-4-function-introduction" target="_blank" rel="noreferrer">4. Software and Hardware Guide / 4.4 WonderLens AI vision module / 4.4.4 Function Introduction</a>.</strong></li></ul><h4 id="_4-tag-recognition" tabindex="-1">(4) Tag Recognition <a class="header-anchor" href="#_4-tag-recognition" aria-label="Permalink to &quot;(4) Tag Recognition&quot;">​</a></h4><ol><li><p><strong>Entering the Mode</strong></p><p>Return to the main interface and toggle the <strong>Navigation Joystick</strong> until the &quot;Facial Recognition&quot; menu bar appears at the top of the screen.</p></li><li><p><strong>Recognizing Tags</strong></p><p>Aim the camera at the tag. The tag will be outlined with an orange bounding box on the screen, and crosshairs will appear in its center.</p><img loading="lazy" height="905" width="1200" src="'+y+'" class="common_img" style="width:500px;aspect-ratio:1200 / 905;"><p>The WonderLens AI vision module can simultaneously recognize multiple tags with identical or different IDs.</p><img loading="lazy" height="905" width="1200" src="'+w+'" class="common_img" style="width:500px;aspect-ratio:1200 / 905;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Maintain an appropriate distance from the tag so that the module can outline it for detection. If the tag is positioned too far from the WonderLens AI vision module, the tag will appear too small in the frame, preventing the module from recognizing it.</strong></p></div></li></ol><h4 id="_5-line-following" tabindex="-1">(5) Line Following <a class="header-anchor" href="#_5-line-following" aria-label="Permalink to &quot;(5) Line Following&quot;">​</a></h4><ol><li><p><strong>Entering the Mode</strong></p><p>Return to the main interface and toggle the <strong>Navigation Joystick</strong> to the right until the &quot;Line Following&quot; menu bar appears at the top of the screen.</p></li><li><p><strong>Learning and Recognizing New Lines</strong></p><p>This function operates similarly to color recognition. The line must be learned prior to use. The learning steps are as follows:</p><p>(1) On the main line following interface, first toggle the <strong>Function Joystick</strong> to the left, then short-press the button corresponding to the pen icon <img loading="lazy" height="47" width="50" src="'+e+'" class="inline-icon" style="width:35px;aspect-ratio:50 / 47;">.</p><img loading="lazy" height="905" width="1200" src="'+f+'" class="common_img" style="width:500px;aspect-ratio:1200 / 905;"><p>(2) Align the crosshairs in the center of the screen with the line to be learned. Ensure that the line appears as straight or vertical as possible in the frame, and adjust the white arrow on the screen to match the direction of the target line.</p><img loading="lazy" height="904" width="1200" src="'+_+'" class="common_img" style="width:500px;aspect-ratio:1200 / 904;"><p>(3) Short-press the button corresponding to the camera icon <img loading="lazy" height="38" width="46" src="'+i+'" class="inline-icon" style="width:40px;aspect-ratio:46 / 38;"> to start learning. Adjust the lighting and angle to ensure that the white arrow remains stable without jittering, then wait for the learning result prompt. <strong>If learning fails, change the lighting conditions or use a more vivid color to restore the arrow to a stable state before attempting to learn again.</strong></p><img loading="lazy" height="904" width="1200" src="'+b+'" class="common_img" style="width:500px;aspect-ratio:1200 / 904;"><p>(4) After successful learning, whenever the corresponding line color appears in the frame, the WonderLens AI vision module calculates the region of that color and draws an arrow.</p><img loading="lazy" height="904" width="1200" src="'+x+'" class="common_img" style="width:500px;aspect-ratio:1200 / 904;"><img loading="lazy" height="904" width="1200" src="'+k+'" class="common_img" style="width:500px;aspect-ratio:1200 / 904;"></li></ol><ul><li><strong>For instructions on deleting line IDs and configuring related parameters in line following, refer to <a href="https://wiki.hiwonder.com/projects/AIVisionKit/en/latest/docs/4.%20Software%20and%20Hardware%20Guide.html#_4-4-4-function-introduction" target="_blank" rel="noreferrer">4. Software and Hardware Guide / 4.4 WonderLens AI vision module / 4.4.4 Function Introduction</a>.</strong></li></ul><h4 id="_6-number-recognition" tabindex="-1">(6) Number Recognition <a class="header-anchor" href="#_6-number-recognition" aria-label="Permalink to &quot;(6) Number Recognition&quot;">​</a></h4><ol><li><p><strong>Entering the Mode</strong></p><p>Return to the main interface and toggle the <strong>Navigation Joystick</strong> to the right until the &quot;Number Recognition&quot; menu bar appears at the top of the screen.</p></li><li><p><strong>Recognizing Numbers</strong></p><p>Aim the camera at the number cards to perform classification testing. Each number card corresponds to a specific number. During operation, the screen displays the number with the highest confidence level along with its confidence value. A confidence value closer to 1.0 indicates a more reliable recognition result.</p><img loading="lazy" height="905" width="1200" src="'+v+'" class="common_img" style="width:500px;aspect-ratio:1200 / 905;"><table tabindex="0"><thead><tr><th style="text-align:center;">Number Card</th><th style="text-align:center;">Number</th><th style="text-align:center;">Number Card</th><th style="text-align:center;">Number</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:216 / 215;" height="215" width="216" src="'+z+'"></td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:216 / 216;" height="216" width="216" src="'+q+'"></td><td style="text-align:center;">2</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:209 / 216;" height="216" width="209" src="'+I+'"></td><td style="text-align:center;">3</td><td style="text-align:center;"><img loading="lazy" height="214" width="216" src="'+P+'" style="width:150px;aspect-ratio:216 / 214;"></td><td style="text-align:center;">4</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:216 / 215;" height="215" width="216" src="'+S+'"></td><td style="text-align:center;">5</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The optimal distance between the card and the camera is approximately 15 to 20 cm. Avoid excessively dim ambient lighting, and use a solid background, preferably white, for optimal recognition.</strong></p></div></li></ol><h4 id="_7-traffic-sign-recognition" tabindex="-1">(7) Traffic Sign Recognition <a class="header-anchor" href="#_7-traffic-sign-recognition" aria-label="Permalink to &quot;(7) Traffic Sign Recognition&quot;">​</a></h4><ol><li><p><strong>Entering the Mode</strong></p><p>Return to the main interface and toggle the <strong>Navigation Joystick</strong> to the right until the &quot;Traffic Sign Recognition&quot; menu bar appears at the top of the screen.</p></li><li><p><strong>Recognizing Traffic Signs</strong></p><p>Aim the camera at the traffic sign cards to perform classification testing. Each card corresponds to a different ID. During operation, the screen displays the ID with the highest confidence level along with its confidence value. A confidence value closer to 1.0 indicates a more reliable recognition result.</p><img loading="lazy" height="905" width="1200" src="'+A+'" class="common_img" style="width:500px;aspect-ratio:1200 / 905;"><table tabindex="0"><thead><tr><th style="text-align:center;">Traffic Sign Card</th><th style="text-align:center;">ID</th><th style="text-align:center;">Traffic Sign Card</th><th style="text-align:center;">ID</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:94 / 96;" height="96" width="94" src="'+C+'"></td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:96 / 96;" height="96" width="96" src="'+j+'"></td><td style="text-align:center;">2</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:94 / 96;" height="96" width="94" src="'+D+'"></td><td style="text-align:center;">3</td><td style="text-align:center;"><img loading="lazy" height="93" width="93" src="'+T+'" style="width:150px;aspect-ratio:93 / 93;"></td><td style="text-align:center;">4</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:98 / 97;" height="97" width="98" src="'+O+'"></td><td style="text-align:center;">5</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table></li></ol><h4 id="_8-image-classification" tabindex="-1">(8) Image Classification <a class="header-anchor" href="#_8-image-classification" aria-label="Permalink to &quot;(8) Image Classification&quot;">​</a></h4><ol><li><p><strong>Entering the Mode</strong></p><p>Return to the main interface and toggle the <strong>Navigation Joystick</strong> to the right until the &quot;Image Classification&quot; menu bar appears at the top of the screen.</p></li><li><p><strong>Classifying Images</strong></p><p>After launching the image classification function, test classification using the included waste classification cards. Each card corresponds to a different ID. During operation, the screen displays the ID with the highest confidence level along with its confidence value. A confidence value closer to 1.0 indicates a more reliable recognition result.</p><img loading="lazy" height="905" width="1200" src="'+R+'" class="common_img" style="width:500px;aspect-ratio:1200 / 905;"><table tabindex="0"><thead><tr><th style="text-align:center;">Waste Card</th><th style="text-align:center;">ID</th><th style="text-align:center;">Waste Card</th><th style="text-align:center;">ID</th></tr></thead><tbody><tr><td style="text-align:center;">White background</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="96" width="98" src="'+E+'" style="width:150px;aspect-ratio:98 / 96;"></td><td style="text-align:center;">2</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="95" width="96" src="'+L+'" style="width:150px;aspect-ratio:96 / 95;"></td><td style="text-align:center;">3</td><td style="text-align:center;"><img loading="lazy" height="95" width="96" src="'+F+'" style="width:150px;aspect-ratio:96 / 95;"></td><td style="text-align:center;">4</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:96 / 96;" height="96" width="96" src="'+W+'"></td><td style="text-align:center;">5</td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:95 / 96;" height="96" width="95" src="'+B+'"></td><td style="text-align:center;">6</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:96 / 96;" height="96" width="96" src="'+N+'"></td><td style="text-align:center;">7</td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:97 / 96;" height="96" width="97" src="'+V+'"></td><td style="text-align:center;">8</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:96 / 95;" height="95" width="96" src="'+G+'"></td><td style="text-align:center;">9</td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:94 / 95;" height="95" width="94" src="'+M+'"></td><td style="text-align:center;">10</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:97 / 96;" height="96" width="97" src="'+J+'"></td><td style="text-align:center;">11</td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:95 / 96;" height="96" width="95" src="'+K+'"></td><td style="text-align:center;">12</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:98 / 95;" height="95" width="98" src="'+H+'"></td><td style="text-align:center;">13</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table></li></ol><h4 id="_9-feature-learning" tabindex="-1">(9) Feature Learning <a class="header-anchor" href="#_9-feature-learning" aria-label="Permalink to &quot;(9) Feature Learning&quot;">​</a></h4><ol><li><p><strong>Entering the Mode</strong></p><p>Return to the main interface and toggle the <strong>Navigation Joystick</strong> to the right until the &quot;Feature Learning&quot; menu bar appears at the top of the screen.</p></li><li><p><strong>Learning Features</strong></p><p>(1) On the main feature learning screen, toggle the <strong>Function Joystick</strong> to the left toward the pen icon <img loading="lazy" height="47" width="50" src="'+e+'" class="inline-icon" style="width:35px;aspect-ratio:50 / 47;"> to enter the learning interface.</p><img loading="lazy" height="905" width="1200" src="'+U+'" class="common_img" style="width:500px;aspect-ratio:1200 / 905;"><p>(2) Move the WonderLens AI vision module to frame the target, then press the <strong>Function Joystick</strong> button corresponding to the camera icon <img loading="lazy" height="38" width="46" src="'+i+'" class="inline-icon" style="width:40px;aspect-ratio:46 / 38;"> and wait for the module to finish learning.</p><img loading="lazy" height="905" width="1200" src="'+Q+'" class="common_img" style="width:500px;aspect-ratio:1200 / 905;"><p>(3) After learning is completed, the displayed ID and P values are no longer 0. In this display, P represents the confidence level, where a value closer to 1 indicates higher similarity. ID represents the ID of the learned image that best matches the current frame.</p><img loading="lazy" height="904" width="1200" src="'+$+'" class="common_img" style="width:500px;aspect-ratio:1200 / 904;"></li></ol><ul><li><strong>For instructions on deleting IDs in feature learning, refer to <a href="https://wiki.hiwonder.com/projects/AIVisionKit/en/latest/docs/4.%20Software%20and%20Hardware%20Guide.html#_4-4-4-function-introduction" target="_blank" rel="noreferrer">4. Software and Hardware Guide / 4.4 WonderLens AI vision module / 4.4.4 Function Introduction</a>.</strong></li></ul><p><a id="section-2-2"></a></p><h2 id="_2-2-wonderecho-ai-voice-module-basic-experience" tabindex="-1">2.2 WonderEcho AI Voice Module Basic Experience <a class="header-anchor" href="#_2-2-wonderecho-ai-voice-module-basic-experience" aria-label="Permalink to &quot;2.2 WonderEcho AI Voice Module Basic Experience&quot;">​</a></h2><h3 id="_2-2-1-powering-on-the-device" tabindex="-1">2.2.1 Powering On the Device <a class="header-anchor" href="#_2-2-1-powering-on-the-device" aria-label="Permalink to &quot;2.2.1 Powering On the Device&quot;">​</a></h3><p>Power the module using a Type-C cable connected to a computer port or a USB power adapter, as shown in the following figure:</p><img loading="lazy" height="470" width="430" src="'+nt+'" class="common_img" style="width:250px;aspect-ratio:430 / 470;"><h3 id="_2-2-2-voice-interaction" tabindex="-1">2.2.2 Voice Interaction <a class="header-anchor" href="#_2-2-2-voice-interaction" aria-label="Permalink to &quot;2.2.2 Voice Interaction&quot;">​</a></h3><p>The WonderEcho AI voice module operates using voice command wake-up. <strong>Speak the wake word Hello Hiwonder to activate the voice interaction module before issuing any commands.</strong> When the module responds with &quot;I&#39;m here.&quot;, it indicates that the module is ready for speech recognition.</p><p>Taking the command word <strong>Going straight</strong> as an example, wake up the module first before issuing the command word <strong>Going straight</strong>.</p><ul><li><p>Step 1: Say <strong>Hello Hiwonder</strong> to wake up the module.</p><img loading="lazy" height="270" width="211" src="'+xt+'" class="common_img" style="width:200px;aspect-ratio:211 / 270;"></li><li><p>Step 2: Say the command word <strong>Going straight</strong> to trigger the corresponding voice broadcast.</p><img loading="lazy" height="270" width="211" src="'+rt+'" class="common_img" style="width:200px;aspect-ratio:211 / 270;"></li><li><p>Say the following command words to the voice interaction module, and WonderEcho will broadcast the corresponding responses:</p><img loading="lazy" height="531" width="802" src="'+kt+'" class="common_img" style="width:500px;aspect-ratio:802 / 531;"></li></ul><h2 id="_2-3-hardware-preparation" tabindex="-1">2.3 Hardware Preparation <a class="header-anchor" href="#_2-3-hardware-preparation" aria-label="Permalink to &quot;2.3 Hardware Preparation&quot;">​</a></h2><h3 id="_2-3-1-powering-on" tabindex="-1">2.3.1 Powering On <a class="header-anchor" href="#_2-3-1-powering-on" aria-label="Permalink to &quot;2.3.1 Powering On&quot;">​</a></h3><p>Toggle the power switch to the <strong>ON</strong> position. When the power LED indicators on the controller illuminate, startup is successful.</p><img loading="lazy" height="1200" width="2020" src="'+vt+'" class="common_img" style="width:500px;aspect-ratio:2020 / 1200;"><h3 id="_2-3-2-charging" tabindex="-1">2.3.2 Charging <a class="header-anchor" href="#_2-3-2-charging" aria-label="Permalink to &quot;2.3.2 Charging&quot;">​</a></h3><ol><li>Ensure that the power switch of the controller is set to the <strong>OFF</strong> position. Connect one end of the Type-C cable to the charging port of the controller and the other end to a USB charger.</li></ol><img loading="lazy" height="1200" width="1200" src="'+zt+'" class="common_img" style="width:400px;aspect-ratio:1200 / 1200;"><ol start="2"><li>During charging, the LED indicators on the controller display the current charging status. When the battery is fully charged, all four white LEDs remain continuously lit. Disconnect the power cable promptly after charging is complete to prevent overcharging.</li></ol><img loading="lazy" height="2000" width="2000" src="'+qt+'" class="common_img" style="width:400px;aspect-ratio:2000 / 2000;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The power switch must be set to the OFF position during charging. Otherwise, the battery may fail to charge fully. Disconnect the charger and power cable promptly once charging is complete to prevent battery damage caused by overcharging.</strong></p></div><h2 id="_2-4-software-preparation" tabindex="-1">2.4 Software Preparation <a class="header-anchor" href="#_2-4-software-preparation" aria-label="Permalink to &quot;2.4 Software Preparation&quot;">​</a></h2><h3 id="_2-4-1-downloading-graphical-programming-software" tabindex="-1">2.4.1 Downloading Graphical Programming Software <a class="header-anchor" href="#_2-4-1-downloading-graphical-programming-software" aria-label="Permalink to &quot;2.4.1 Downloading Graphical Programming Software&quot;">​</a></h3><p><a href="https://k12.hiwonder.com.cn/download/pcSoftware?get_pc=1&amp;os=windows" target="_blank" rel="noreferrer">Download WonderLab Programming Software for Windows</a></p><img loading="lazy" height="1040" width="1920" src="'+It+'" class="common_img" style="width:800px;aspect-ratio:1920 / 1040;"><h3 id="_2-4-2-installing-wonderlab-programming-software" tabindex="-1">2.4.2 Installing WonderLab Programming Software <a class="header-anchor" href="#_2-4-2-installing-wonderlab-programming-software" aria-label="Permalink to &quot;2.4.2 Installing WonderLab Programming Software&quot;">​</a></h3><ol><li>Open the <strong>WonderLab .exe</strong> installation package.</li></ol><img loading="lazy" height="204" width="192" src="'+Z+'" class="common_img" style="width:80px;aspect-ratio:192 / 204;"><ol start="2"><li>Select the desired language, then click <strong>OK</strong>.</li></ol><img loading="lazy" height="162" width="349" src="'+X+'" class="common_img" style="width:350px;aspect-ratio:349 / 162;"><ol start="3"><li>Select the installation destination folder, then click <strong>Next</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+Y+'" class="common_img" style="width:500px;aspect-ratio:582 / 415;"><ol start="4"><li>Click <strong>Next</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+tt+'" class="common_img" style="width:500px;aspect-ratio:582 / 415;"><ol start="5"><li>Click <strong>Install</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+et+'" class="common_img" style="width:500px;aspect-ratio:582 / 415;"><img loading="lazy" height="415" width="582" src="'+it+'" class="common_img" style="width:500px;aspect-ratio:582 / 415;"><ol start="6"><li>Once installation is complete, click <strong>Finish</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+ot+'" class="common_img" style="width:500px;aspect-ratio:582 / 415;"><h2 id="_2-5-introductory-projects" tabindex="-1">2.5 Introductory Projects <a class="header-anchor" href="#_2-5-introductory-projects" aria-label="Permalink to &quot;2.5 Introductory Projects&quot;">​</a></h2><h3 id="_2-5-1-buzzer-alarm" tabindex="-1">2.5.1 Buzzer Alarm <a class="header-anchor" href="#_2-5-1-buzzer-alarm" aria-label="Permalink to &quot;2.5.1 Buzzer Alarm&quot;">​</a></h3><h4 id="_1-learning-objectives" tabindex="-1">(1) Learning Objectives <a class="header-anchor" href="#_1-learning-objectives" aria-label="Permalink to &quot;(1) Learning Objectives&quot;">​</a></h4><ol><li><strong>Knowledge Objectives</strong>: Get familiar with basic operations of the WonderLab programming platform. Understand the functions, sound-producing principles, and parameter meanings of volume, pitch, and beat for the buzzer module on the AiBlock controller. Master the basic programming logic of main loops and button event triggering.</li><li><strong>Skill Objectives</strong>: Proficiently complete basic operations of creating new projects and adding controller extensions in the programming software. Able to independently construct graphical programs for buzzer sounding and volume adjustment. Master the complete process of program connection, upload, and debugging.</li><li><strong>Literacy Objectives</strong>: Establish computational thinking for coordinating hardware with software routines. Understand the operational role of event-driven trigger mechanisms. Develop practical hands-on assembly and systematic program-debugging skills.</li></ol><h4 id="_2-adding-extensions" tabindex="-1">(2) Adding Extensions <a class="header-anchor" href="#_2-adding-extensions" aria-label="Permalink to &quot;(2) Adding Extensions&quot;">​</a></h4><ul><li>Select <strong>AI Blocks Board</strong> under the <strong>Controller</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+Pt+'" class="common_img" style="width:800px;aspect-ratio:1920 / 1040;"><h4 id="_3-core-blocks" tabindex="-1">(3) Core Blocks <a class="header-anchor" href="#_3-core-blocks" aria-label="Permalink to &quot;(3) Core Blocks&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:554 / 59;" height="59" width="554" src="'+st+'"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:108 / 95;" height="95" width="108" src="'+o+'"></td><td style="text-align:left;">Play the designated musical note according to the configured parameters</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:428 / 88;" height="88" width="428" src="'+St+'"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:108 / 95;" height="95" width="108" src="'+o+'"></td><td style="text-align:left;">Adjust the volume level of the buzzer</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:589 / 193;" height="193" width="589" src="'+lt+'"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:108 / 95;" height="95" width="108" src="'+o+'"></td><td style="text-align:left;">Trigger the corresponding program routine when the button is short-pressed</td></tr></tbody></table><h4 id="_4-program-description-and-upload" tabindex="-1">(4) Program Description and Upload <a class="header-anchor" href="#_4-program-description-and-upload" aria-label="Permalink to &quot;(4) Program Description and Upload&quot;">​</a></h4><ul><li><p>Complete Program</p><ol><li>Upon power-on, the main program executes continuously in a loop. Inside the loop, tone C2 plays continuously at a 1/2 beat in background mode, with a 1 s pause after each playback.</li><li>Independent button controls are configured concurrently. Short-pressing the left button sets the buzzer volume to 100 and pauses for 2 s. Short-pressing the right button sets the buzzer volume to 50 and pauses for 2 s. The buttons can modify the buzzer volume parameter at any time during execution.</li></ol><img loading="lazy" height="741" width="768" src="'+At+'" class="common_img" style="width:500px;aspect-ratio:768 / 741;"></li><li><p>Program Upload</p><p>Click <strong>Connect device</strong>, select the serial port, then click the upload button to complete the program transfer and test the execution results.</p><img loading="lazy" height="360" width="640" src="'+n+'" class="common_img" style="width:800px;aspect-ratio:640 / 360;"></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/13cA6QmQoL5mcmanTN-vfpmCJO58xmOD7?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h4 id="_5-execution-result" tabindex="-1">(5) Execution Result <a class="header-anchor" href="#_5-execution-result" aria-label="Permalink to &quot;(5) Execution Result&quot;">​</a></h4><p>The device repeatedly plays tone C2 in the background for a 1/2-beat duration with a 1 s interval between notes. Short-pressing the left button adjusts the buzzer volume to 100 with a 2 s delay. Short-pressing the right button adjusts the buzzer volume to 50 with a 2 s delay.</p><h3 id="_2-5-2-dual-state-intelligent-start-stop-control-for-line-following" tabindex="-1">2.5.2 Dual-State Intelligent Start-Stop Control for Line Following <a class="header-anchor" href="#_2-5-2-dual-state-intelligent-start-stop-control-for-line-following" aria-label="Permalink to &quot;2.5.2 Dual-State Intelligent Start-Stop Control for Line Following&quot;">​</a></h3><h4 id="_1-learning-objectives-1" tabindex="-1">(1) Learning Objectives <a class="header-anchor" href="#_1-learning-objectives-1" aria-label="Permalink to &quot;(1) Learning Objectives&quot;">​</a></h4><ol><li><strong>Knowledge Objectives</strong>: Get familiar with extension adding operations in the WonderLab programming platform. Understand the functions and working principles of the 6-channel line-tracking sensor, RGB light module, dot matrix module, 180° block servo, and block long motor. Master the basic programming logic of reading sensor states and multi-condition branch judgment.</li><li><strong>Skill Objectives</strong>: Proficiently complete extension adding and hardware wiring operations for multiple module types. Able to independently construct graphical programs for line-tracking detection and driving the dot matrix, RGB light, servo, and motor to work collaboratively. Master the complete process of program connection, upload, and debugging.</li><li><strong>Literacy Objectives</strong>: Develop computational thinking for coordinating multi-hardware interactions. Understand the functional role of sensor-based condition assessments. Cultivate analytical debugging abilities and comprehensive hands-on engineering skills.</li></ol><h4 id="_2-hardware-wiring" tabindex="-1">(2) Hardware Wiring <a class="header-anchor" href="#_2-hardware-wiring" aria-label="Permalink to &quot;(2) Hardware Wiring&quot;">​</a></h4><ul><li>Connect the 6-channel line follower sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</li><li>Connect the dot matrix module to port <strong>B</strong> of the controller using a 4-pin module cable.</li><li>Connect the RGB light module to port <strong>C</strong> of the controller using a 4-pin module cable.</li><li>Connect the 180° block servo to port <strong>S1</strong> of the controller using a 3-pin servo cable.</li><li>Connect the long motor to port <strong>M1</strong> of the controller using a modular servo cable.</li></ul><img loading="lazy" height="1726" width="3918" src="'+Ct+'" class="common_img" style="width:500px;aspect-ratio:3918 / 1726;"><h4 id="_3-adding-extensions" tabindex="-1">(3) Adding Extensions <a class="header-anchor" href="#_3-adding-extensions" aria-label="Permalink to &quot;(3) Adding Extensions&quot;">​</a></h4><ul><li>Select <strong>6 Line follow sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+at+'" class="common_img" style="width:800px;aspect-ratio:1920 / 1040;"><ul><li>Select <strong>180° servo</strong> and <strong>Long motor</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+ct+'" class="common_img" style="width:800px;aspect-ratio:1920 / 1040;"><ul><li>Select <strong>Dot matrix module</strong> and <strong>RGB module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+jt+'" class="common_img" style="width:800px;aspect-ratio:1920 / 1040;"><h4 id="_4-core-blocks" tabindex="-1">(4) Core Blocks <a class="header-anchor" href="#_4-core-blocks" aria-label="Permalink to &quot;(4) Core Blocks&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:680 / 57;" height="57" width="680" src="'+gt+'"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:108 / 95;" height="95" width="108" src="'+t+'"></td><td style="text-align:left;">Select the motor port, set the speed percentage, configure clockwise or counterclockwise rotation, and start the motor</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:255 / 77;" height="77" width="255" src="'+ht+'"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:108 / 95;" height="95" width="108" src="'+t+'"></td><td style="text-align:left;">Select the target motor port and stop the corresponding motor immediately</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:625 / 65;" height="65" width="625" src="'+dt+'"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:108 / 95;" height="95" width="108" src="'+t+'"></td><td style="text-align:left;">Select the servo port, set the speed percentage and target angle, choose automatic delay or no delay, and rotate the servo to the specified angle</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:328 / 62;" height="62" width="328" src="'+Dt+'"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:108 / 95;" height="95" width="108" src="'+t+'"></td><td style="text-align:left;">Select the target servo port and stop the current servo movement so that the servo holds its current position</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:559 / 54;" height="54" width="559" src="'+pt+'"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:106 / 65;" height="65" width="106" src="'+mt+'"></td><td style="text-align:left;">Read the black and white line detection status across all channels of the 6-channel line follower sensor to acquire tracking path information</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:280 / 64;" height="64" width="280" src="'+ut+'"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:108 / 94;" height="94" width="108" src="'+r+'"></td><td style="text-align:left;">Select the dot matrix module port and display a custom drawn pattern</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:414 / 64;" height="64" width="414" src="'+yt+'"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:108 / 94;" height="94" width="108" src="'+r+'"></td><td style="text-align:left;">Select the RGB light module port and set the desired illumination color</td></tr></tbody></table><h4 id="_5-program-description-and-upload" tabindex="-1">(5) Program Description and Upload <a class="header-anchor" href="#_5-program-description-and-upload" aria-label="Permalink to &quot;(5) Program Description and Upload&quot;">​</a></h4><ul><li><p>Complete Program</p><ol><li>The program initializes the 6-channel line follower sensor connected to port <strong>A</strong>.</li><li>The main program enters a continuous loop to monitor the sensor status. <ul><li>When the channels of the 6-channel line follower sensor detect a black line, the dot matrix module on port <strong>B</strong> displays the text &quot;Hello&quot;, the RGB light module on port <strong>C</strong> illuminates in cyan, servo <strong>S1</strong> rotates to 10° at 80% speed without delay, and motor <strong>M1</strong> stops rotating.</li><li>If no black line is detected, the program further determines whether the sensor detects a white surface. Under this condition, the dot matrix module on port <strong>B</strong> draws a heart pattern, the RGB light module on port <strong>C</strong> illuminates in yellow, motor <strong>M1</strong> starts rotating clockwise at 50% speed, and servo <strong>S1</strong> stops operating. The process then repeats in the loop.</li></ul></li></ol><img loading="lazy" height="697" width="591" src="'+Tt+'" class="common_img" style="width:500px;aspect-ratio:591 / 697;"></li><li><p>Program Upload</p><p>Click <strong>Connect device</strong>, select the serial port, then click the upload button to complete the program transfer and test the execution results.</p><img loading="lazy" height="360" width="640" src="'+n+'" class="common_img" style="width:800px;aspect-ratio:640 / 360;"></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/13cA6QmQoL5mcmanTN-vfpmCJO58xmOD7?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h4 id="_6-execution-result" tabindex="-1">(6) Execution Result <a class="header-anchor" href="#_6-execution-result" aria-label="Permalink to &quot;(6) Execution Result&quot;">​</a></h4><p>Upon powering on the device, the line follower sensor is initialized first. The program continuously loops to detect line following conditions. When a black line is detected, the dot matrix display shows Hello, the RGB light turns cyan, the servo rotates, and the motor stops. When a white surface is detected, the dot matrix display shows a heart, the RGB light switches to yellow, the motor rotates clockwise, and the servo stops.</p>',102)])])}const Kt=wt(Ot,[["render",Rt]]);export{Jt as __pageData,Kt as default};
